import os
from typing import Any, Dict, List, Optional

import requests


class DocumentLayoutExtractor:
    """
    Extracts OCR and layout elements from a document using Azure AI Document Intelligence
    (formerly Form Recognizer) prebuilt-layout model.
    """

    def __init__(self, endpoint: Optional[str] = None, api_key: Optional[str] = None):
        self.endpoint = (endpoint or os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT") or "").rstrip("/")
        self.api_key = api_key or os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_API_KEY") or os.environ.get("AZURE_FORM_RECOGNIZER_KEY")
        if not self.endpoint or not self.api_key:
            raise ValueError(
                "Missing Azure Document Intelligence credentials. "
                "Set AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT and AZURE_DOCUMENT_INTELLIGENCE_API_KEY."
            )

    def analyze_document(self, file_path: str) -> Dict[str, Any]:
        analyze_url = f"{self.endpoint}/documentintelligence/documentModels/prebuilt-layout:analyze?api-version=2024-02-29-preview"
        headers = {
            "Ocp-Apim-Subscription-Key": self.api_key,
            "Content-Type": "application/octet-stream",
        }

        with open(file_path, "rb") as f:
            resp = requests.post(analyze_url, headers=headers, data=f, timeout=120)

        resp.raise_for_status()
        operation_url = resp.headers.get("operation-location")
        if not operation_url:
            raise RuntimeError("Azure Document Intelligence did not return an operation-location header.")

        result = self._poll_result(operation_url)
        return self._normalize_result(result)

    def _poll_result(self, operation_url: str, timeout_seconds: int = 180, interval_seconds: float = 1.5) -> Dict[str, Any]:
        headers = {"Ocp-Apim-Subscription-Key": self.api_key}
        elapsed = 0.0
        while elapsed < timeout_seconds:
            resp = requests.get(operation_url, headers=headers, timeout=60)
            resp.raise_for_status()
            payload = resp.json()
            status = payload.get("status")
            if status in ("succeeded", "failed"):
                if status == "failed":
                    raise RuntimeError(f"Document analysis failed: {payload}")
                return payload
            import time

            time.sleep(interval_seconds)
            elapsed += interval_seconds

        raise TimeoutError("Timed out waiting for Azure Document Intelligence analysis result.")

    def _normalize_result(self, payload: Dict[str, Any]) -> Dict[str, Any]:
        analyze_result = payload.get("analyzeResult", {})
        pages = analyze_result.get("pages", [])
        tables = analyze_result.get("tables", [])
        paragraphs = analyze_result.get("paragraphs", [])
        styles = analyze_result.get("styles", [])
        content = analyze_result.get("content", "")

        blocks = []
        for paragraph in paragraphs:
            blocks.append(
                {
                    "role": paragraph.get("role"),
                    "content": paragraph.get("content"),
                    "spans": paragraph.get("spans", []),
                    "boundingRegions": paragraph.get("boundingRegions", []),
                }
            )

        lines = []
        for page in pages:
            for line in page.get("lines", []):
                lines.append(
                    {
                        "pageNumber": page.get("pageNumber"),
                        "content": line.get("content"),
                        "spans": line.get("spans", []),
                        "polygon": line.get("polygon", []),
                    }
                )

        table_data = []
        for table in tables:
            cells = []
            for cell in table.get("cells", []):
                cells.append(
                    {
                        "rowIndex": cell.get("rowIndex"),
                        "columnIndex": cell.get("columnIndex"),
                        "rowSpan": cell.get("rowSpan"),
                        "columnSpan": cell.get("columnSpan"),
                        "content": cell.get("content"),
                        "kind": cell.get("kind"),
                        "boundingRegions": cell.get("boundingRegions", []),
                    }
                )
            table_data.append(
                {
                    "rowCount": table.get("rowCount"),
                    "columnCount": table.get("columnCount"),
                    "boundingRegions": table.get("boundingRegions", []),
                    "cells": cells,
                }
            )

        return {
            "content": content,
            "blocks": blocks,
            "lines": lines,
            "tables": table_data,
            "styles": styles,
            "pages": pages,
            "raw": payload,
        }


def extract_layout(file_path: str, endpoint: Optional[str] = None, api_key: Optional[str] = None) -> Dict[str, Any]:
    extractor = DocumentLayoutExtractor(endpoint=endpoint, api_key=api_key)
    return extractor.analyze_document(file_path)
